ALTER TABLE public.team_member_achievement ADD COLUMN achievement_category_id bigint;
ALTER TABLE public.team_member_achievement
    ADD CONSTRAINT fk_team_member_achievement__achievement_category_id
    FOREIGN KEY (achievement_category_id) REFERENCES public.achievement_category(id) ON DELETE SET NULL;

CREATE OR REPLACE FUNCTION public.roster_json_categories(raw text)
RETURNS TABLE(code text)
LANGUAGE plpgsql
AS $$
BEGIN
    IF raw IS NULL OR btrim(raw) = '' THEN
        RETURN;
    END IF;
    RETURN QUERY
    SELECT jsonb_array_elements_text(parsed -> 'categories')
    FROM (SELECT raw::jsonb AS parsed) s
    WHERE jsonb_typeof(parsed) = 'object'
      AND jsonb_typeof(parsed -> 'categories') = 'array';
EXCEPTION WHEN others THEN
    RETURN;
END;
$$;
